  // Unescape Gleam string escapes (standard C-like): \n \t \r pass through;
  // \\ -> \, \" -> ", \/ -> /, etc.
  const unescape = (s) =>
    s.replace(/\\(.)/g, (_, c) =>
      c === "n" ? "\n" : c === "t" ? "\t" : c === "r" ? "\r" : c,
    );
